/// <summary>
/// GUPPricingAttribute of table <c>InventTableModule</c> field UnitId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTableModule, UnitId), tableStr(UnitOfMeasure), fieldStr(UnitOfMeasure, Symbol))]
internal class GUPPricingAttributeInventTableModuleSalesUnitId extends GUPPricingAttributeInventTableModuleSales implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return strFmt("%1 - %2", enum2Str(ModuleInventPurchSales::Sales), fieldPName(InventTableModule, UnitId));
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTableModule   inventTableModule;
    UnitOfMeasure       unitOfMeasure;

    while select UnitId from inventTableModule
        join unitOfMeasure
        group by Symbol, UnitOfMeasureClass
        where inventTableModule.UnitId == UnitOfMeasure.Symbol
            && InventTablemodule.ModuleType == ModuleInventPurchSales::Sales
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(unitOfMeasure.Symbol, enum2Str(unitOfMeasure.UnitOfMeasureClass));
        ret.add(valueObject);
    }
    return ret;
}
